const s = "粘贴 payload";
[...s].map(c => {
  const n = c.charCodeAt(0);
  if (n >= 65 && n <= 90) return String.fromCharCode((n - 65 + 13) % 26 + 65);
  if (n >= 97 && n <= 122) return String.fromCharCode((n - 97 + 13) % 26 + 97);
  return c;
}).join("")

const s = "粘贴 payload";
[...s].map(c => {
  const n = c.charCodeAt(0);
  if (n >= 65 && n <= 90) return String.fromCharCode((n - 65 - 3 + 26) % 26 + 65);
  if (n >= 97 && n <= 122) return String.fromCharCode((n - 97 - 3 + 26) % 26 + 97);
  return c;
}).join("")

const s = "粘贴 payload";
[...s].map(c => {
  const n = c.charCodeAt(0);
  if (n >= 65 && n <= 90) return String.fromCharCode(90 - (n - 65));
  if (n >= 97 && n <= 122) return String.fromCharCode(122 - (n - 97));
  return c;
}).join("")
